  const inputSha=sha256(profiles.map(x=>[x.sampleId,x.profileId])),run=(await client.query(`INSERT INTO sample_cluster_runs(job_id,algorithm_selection_id,algorithm_version,input_sha256,profile_count)VALUES($1,$2,$3,$4,$5)RETURNING *`,[job.id,job.algorithm_selection_id,CLUSTER_ALGORITHM_VERSION,inputSha,profiles.length])).rows[0];
